UPDATE lessons SET title='Year 3, Week 31, Lesson 1: Dreaming stories and cultural protocols', data=json_patch(data,'{"child_mission":"When learning about Dreaming stories, students follow cultural protocols: listen respectfully, use approved classroom sources and never invent or alter sacred stories.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nList three respectful behaviours for listening to a story shared through an approved classroom resource.\n\nFEEDBACK\nBehaviours: listen quietly; do not invent details; acknowledge the source community when the resource names it; ask before retelling beyond class.\n\nCHECK\nMaking up a \"Dreaming-style\" story is not respectful learning.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nUsing only approved resources available at home/school, complete a respect checklist: source named, protocols followed, what must not be changed and one question to ask an adult before any retell.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"When learning about Dreaming stories, students follow cultural protocols: listen respectfully, use approved classroom sources and never invent or alter sacred stories.","lesson_number":1,"lesson_role":"Reading","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-RECOM-01","EN2-UARL-01"],"parent_notes":"Parent: Marking guidance for the independe